import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor gelu_tanh_forward(torch::Tensor x);
"""

gelu_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cmath>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float gelu_tanh_scalar(float x) {
  const float k0 = 0.79788456080286535588f; // sqrt(2/pi)
  const float k1 = 0.044715f;
  float x3 = x * x * x;
  float t = __tanhf(k0 * (x + k1 * x3));
  return 0.5f * x * (1.0f + t);
}

__global__ void gelu_tanh_cute_kernel(
    const float4* __restrict__ X4,
    float4* __restrict__ Y4,
    const float* __restrict__ Xs,
    float* __restrict__ Ys,
    long long vec_total,
    long long total)
{
  constexpr int Threads = 256;
  constexpr int VecPerThread = 4; // each thread processes 4 float4 (16 floats) per tile for deeper memory-level parallelism

  // CUTE global tensors over float4 elements.
  Tensor gX = make_tensor(make_gmem_ptr(X4), make_shape(vec_total), make_stride(Int<1>{}));
  Tensor gY = make_tensor(make_gmem_ptr(Y4), make_shape(vec_total), make_stride(Int<1>{}));

  auto cta_tiler = Int<Threads * VecPerThread>{};
  auto thr_layout = make_layout(make_shape(Int<Threads>{}), make_stride(Int<1>{}));
  const long long num_tiles = (vec_total + (long long)(Threads * VecPerThread) - 1) / (long long)(Threads * VecPerThread);
  // Grid-stride over CUTE tiles: handles arbitrary sizes with a bounded grid.
  for (long long tile = blockIdx.x; tile < num_tiles; tile += gridDim.x) {
    const long long idx0 = tile * (Threads * VecPerThread) + threadIdx.x;
    Tensor tgX = local_tile(gX, cta_tiler, tile);
    Tensor tgY = local_tile(gY, cta_tiler, tile);
    Tensor tX = local_partition(tgX, thr_layout, threadIdx.x);
    Tensor tY = local_partition(tgY, thr_layout, threadIdx.x);
    // Issue all vectorized loads before compute/stores to expose
    // memory-level parallelism (2 outstanding float4 loads per thread).
    float4 v[VecPerThread];
    bool valid[VecPerThread];
    #pragma unroll
    for (int j = 0; j < VecPerThread; ++j) {
      valid[j] = (idx0 + j * Threads) < vec_total;
      if (valid[j]) {
        v[j] = tX(j);
      }
    }
    #pragma unroll
    for (int j = 0; j < VecPerThread; ++j) {
      if (valid[j]) {
        float4 r;
        r.x = gelu_tanh_scalar(v[j].x);
        r.y = gelu_tanh_scalar(v[j].y);
        r.z = gelu_tanh_scalar(v[j].z);
        r.w = gelu_tanh_scalar(v[j].w);
        tY(j) = r;
      }
    }
  }

  // Scalar tail handled by the same single kernel.
  const long long tail = total - vec_total * 4;
  if (blockIdx.x == 0 && threadIdx.x < tail) {
    const long long i = vec_total * 4 + threadIdx.x;
    Ys[i] = gelu_tanh_scalar(Xs[i]);
  }
}

torch::Tensor gelu_tanh_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  const long long total = (long long)x_c.numel();
  if (total == 0) {
    return y;
  }

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  const long long vec_total = total / 4;
  const long long num_tiles = (vec_total + 1023) / 1024;
  const long long max_grid_ll = 8192;
  long long grid_ll = num_tiles > 0 ? num_tiles : 1;
  if (grid_ll > max_grid_ll) grid_ll = max_grid_ll;
  const unsigned grid_x = (unsigned)grid_ll;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  dim3 grid(grid_x);
  dim3 block(256);
  gelu_tanh_cute_kernel<<<grid, block, 0, stream>>>(
      reinterpret_cast<const float4*>(x_ptr),
      reinterpret_cast<float4*>(y_ptr),
      x_ptr,
      y_ptr,
      vec_total,
      total
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gelu_tanh_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

gelu_ext = load_inline(
    name="cute_gelu_tanh_ext",
    cpp_sources=gelu_cpp_decl,
    cuda_sources=gelu_cuda_src,
    functions=["gelu_tanh_forward"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--expt-relaxed-constexpr"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = gelu_ext

    def forward(self, x):
        return self._ext.gelu_tanh_forward(x)

